                  disableBend && disableThreads && "pointer-events-none",
                )}
              />
            </span>
          )}
        </>
      )}
      {!isReply && !disableThreads && (
        <span
          role="thread vertical line"
          data-thread="vertical"
          className="row-span-3 border-r-(length:--comment-thread-line-stroke) border-border"
        ></span>
      )}
    </div>
  );
};
